import numpy as np

def calculate_T_S(x1, x2, x3, x4):
    """
    Calculates T_S for a set S = {x1, x2, x3, x4} where x1 < x2 < x3 < x4.
    T_S = |x1*x4 - x2*x3| / (x1*x2)
    """
    numerator = abs(x1 * x4 - x2 * x3)
    denominator = x1 * x2
    if denominator == 0:
        return float('inf')
    return numerator / denominator

def find_min_T_for_A(A):
    """
    Finds min(T_S1, ..., T_S5) for the set A = {a1, a2, a3, a4, a5} sorted.
    A must be sorted: a1 < a2 < a3 < a4 < a5.
    """
    a1, a2, a3, a4, a5 = A

    # S1 = {a1, a2, a3, a4}
    TS1 = calculate_T_S(a1, a2, a3, a4)

    # S2 = {a1, a2, a3, a5}
    TS2 = calculate_T_S(a1, a2, a3, a5)

    # S3 = {a1, a2, a4, a5}
    TS3 = calculate_T_S(a1, a2, a4, a5)

    # S4 = {a1, a3, a4, a5}
    TS4 = calculate_T_S(a1, a3, a4, a5)

    # S5 = {a2, a3, a4, a5}
    TS5 = calculate_T_S(a2, a3, a4, a5)

    return min(TS1, TS2, TS3, TS4, TS5)

